{"content": "1|// The rules of the race as one PURE module: no sockets, no real timers, no
2|// Math.random. Everything that touches the outside world is injected —
3|//
4|//   now()      → server time in ms (the master clock every decision is based on)
5|//   send(conn, type, data)      → deliver an outgoing message
6|//   close(conn, code, reason)   → reject a connection
7|//   schedule(delayMs, fn)       → a cancellable-by-us timer (setTimeout / FakeNet.schedule)
8|//
9|// That keeps the whole state machine (lobby → countdown → racing → finished →
10|// ceremony) runnable in node:test against FakeNet pairs, and lets main.mjs
11|// wire the real WebSocket connections into the same handlers.
12|//
13|// Official order: the server settles finish times — clients only REPORT, so a
14|// lying or late client can't change the podium. Ties go to the earliest report
15|// (arrival order), which keeps the result deterministic.
16|import { decode, encode, MAX_PLAYERS } from './protocol.js';
17|
18|// Close codes for turned-away connections (NOTES.md documents these).
19|export const CLOSE_FULL = 4000; // 4 already in the lobby
20|export const CLOSE_STARTED = 4001; // race already running
21|
22|export function createRaceState({
23|  seed,
24|  now = Date.now,
25|  send,
26|  close,
27|  schedule,
28|  countdownMs = 3000,
29|  resultsMs = 2000, // pause between the results table and the podium
30|  ceremonyAfterWinnerMs = 30000, // brief rule: ceremony at latest 30 s after the winner
31|}) {
32|  if (!Number.isInteger(seed) || seed < 0) throw new RangeError('raceState: seed must be a non-negative integer');
33|
34|  const lobby = new Map(); // conn → nothing yet: connected, has not sent join
35|  const players = new Map(); // conn → { id, name, finish: {t, seq} | null, dnf }
36|  let stage = 'lobby';
37|  let nextId = 1;
38|  let reportSeq = 0; // arrival order of finish reports, breaks time ties deterministically
39|  let goAt = null; // shared start moment, sent in countdown and go
40|  let winnerAt = null; // server time when the first finish was reported
41|  let settled = false; // results are out; final stage change pending
42|
43|  const roster = () => Array.from(players.values(), (p) => ({ id: p.id, name: p.name }));
44|  const broadcast = (type, data) => {
45|    for (const [conn, p] of players) if (!p.gone) send(conn, type, data);
46|  };
47|
48|  const toResults = () => {
49|    const byArrival = Array.from(players.values());
50|    const finished = byArrival.filter((p) => p.finish).sort((a, b) => a.finish.t - b.finish.t || a.finish.seq - b.finish.seq);
51|    // Everyone the race settled without a finish time is a DNF (disconnected
52|    // mid-race, or still driving when the 30 s window forced the result).
53|    const dnf = byArrival.filter((p) => !p.finish).sort((a, b) => a.id - b.id);
54|    return [...finished, ...dnf].map((p) => ({
55|      id: p.id, name: p.name, t: p.finish ? p.finish.t : null, dnf: !p.finish,
56|    }));
57|  };
58|
59|  // Ceremony fires when everyone is home (finish or DNF — a disconnect never
60|  // blocks it, brief acceptance criterion) or, at the latest, 30 s after the
61|  // winner crossed. Exactly once.
62|  const settle = () => {
63|    if (settled || winnerAt === null) return;
64|    const allDone = Array.from(players.values()).every((p) => p.finish || p.dnf);
65|    if (!allDone && now() - winnerAt < ceremonyAfterWinnerMs) return;
66|    settled = true;
67|    stage = 'finished';
68|    const results = toResults();
69|    broadcast('stage', { stage: 'finished' });
70|    broadcast('results', { players: results });
71|    schedule(resultsMs, () => {
72|      stage = 'ceremony';
73|      broadcast('stage', { stage: 'ceremony' });
74|    });
75|  };
76|
77|  const startCountdown = () => {
78|    stage = 'countdown';
79|    goAt = now() + countdownMs;
80|    broadcast('stage', { stage: 'countdown' });
81|    broadcast('countdown', { goAt });
82|    schedule(countdownMs, () => {
83|      stage = 'racing';
84|      broadcast('stage', { stage: 'racing' });
85|      broadcast('go', { goAt });
86|    });
87|  };
88|
89|  // --- Handlers the transport layer calls ---
90|
91|  // A new connection. In-lobby and under the cap → wait for join; anything
92|  // else → turned away with a documented close code before any game message.
93|  const connect = (conn) => {
94|    if (stage !== 'lobby') return close(conn, CLOSE_STARTED, 'race already started');
95|    if (players.size + lobby.size >= MAX_PLAYERS) return close(conn, CLOSE_FULL, 'lobby full');
96|    lobby.set(conn);
97|  };
98|
99|  // One text message from a connection, already framed. Malformed or
100|  // out-of-context messages are dropped silently — no state, no crash.
101|  const onMessage = (conn, text) => {
102|    let m = null;
103|    try { m = decode(text); } catch { return; } // unknown/malformed: drop
104|    const player = players.get(conn);
105|    switch (m.type) {
106|      case 'join': {
107|        if (stage !== 'lobby' || !lobby.has(conn) || player) return;
108|        lobby.delete(conn);
109|        players.set(conn, { id: nextId++, name: m.data.name, finish: null, dnf: false });
110|        for (const [c] of players) send(c, 'roster', { players: roster(), seed });
111|        break;
112|      }
113|      case 'name': {
114|        if (stage !== 'lobby' || !player) return;
115|        player.name = m.data.name;
116|        broadcast('roster', { players: roster(), seed });
117|        break;
118|      }
119|      case 'start': {
120|        if (stage !== 'lobby' || !player) return; // start gate: ≥ 2 players
121|        if (players.size >= 2) startCountdown();
122|        break;
123|      }
124|      case 'pos': {
125|        if (!['countdown', 'racing', 'finished'].includes(stage) || !player || player.gone) return;
126|        const { x, z, h, s } = m.data;
127|        for (const [other, peer] of players) if (other !== conn && !peer.gone) send(other, 'posRelay', { id: player.id, x, z, h, s });
128|        break;
129|      }
130|      case 'finish': {
131|        if (!['racing', 'finished'].includes(stage) || !player || player.finish || player.dnf) return;
132|        player.finish = { t: m.data.t, seq: reportSeq++ };
133|        if (winnerAt === null) {
134|          winnerAt = now();
135|          schedule(ceremonyAfterWinnerMs, settle); // the race cannot outlive the winner by 30 s
136|        }
137|        broadcast('finishInfo', { id: player.id, t: m.data.t });
138|        settle();
139|        break;
140|      }
141|      case 'ping': {
142|        if (!player && !lobby.has(conn)) return;
143|        send(conn, 'pong', { t: m.data.t, s: now() }); // echo + server clock reading
144|        break;
145|      }
146|    }
147|  };
148|
149|  // A connection went away. Before join → forget it; a racer → marked gone and
150|  // DNF (stays on the podium, never blocks the ceremony); in the lobby → out
151|  // of the roster.
152|  const disconnect = (conn) => {
153|    if (lobby.delete(conn)) return;
154|    const player = players.get(conn);
155|    if (!player || player.gone) return;
156|    player.gone = true;
157|    if (stage === 'lobby') {
158|      players.delete(conn);
159|      broadcast('disconnect', { id: player.id });
160|      broadcast('roster', { players: roster(), seed });
161|      return;
162|    }
163|    player.dnf = true;
164|    broadcast('disconnect', { id: player.id });
165|    settle(); // a DNF can be the last "result" the race was waiting for
166|  };
167|
168|  return { connect, onMessage, disconnect, get stage() { return stage; }, get roster() { return roster(); } };
169|}", "total_lines": 169, "file_size": 7106, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// FairFahren game server: serves the static game exactly like `npm start`, and
2|// speaks WebSocket on /ws — the race rules (raceState.js) are wired onto every
3|// accepted connection below. Usage: node server/main.mjs [--seed N] [port]
4|import { createServer } from 'node:http';
5|import { resolve } from 'node:path';
6|import { fileURLToPath } from 'node:url';
7|import { serveStatic } from './static.mjs';
8|import { acceptConnection } from './ws.js';
9|import { createRaceState } from './raceState.js';
10|import { encode } from './protocol.js';
11|import { DEFAULT_CITY } from '../src/world/cityGen.js';
12|
13|const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
14|
15|// Composes the game server. `onConnect(conn)` receives every accepted
16|// WebSocket connection: { send(text), close(code, reason), onMessage(cb), onClose(cb) }.
17|export function createGameServer({ onConnect } = {}) {
18|  const server = createServer(serveStatic(ROOT));
19|  const connections = new Set();
20|  server.on('upgrade', (req, socket) => {
21|    if (new URL(req.url, 'http://x').pathname !== '/ws') return socket.destroy();
22|    const conn = acceptConnection(socket, req.headers);
23|    if (!conn) return; // invalid handshake: already answered and destroyed
24|    connections.add(conn);
25|    onConnect?.(conn); // sets conn.onMessage / conn.onClose as it sees fit
26|    // Keep our set tidy whatever the caller did: run our cleanup after theirs.
27|    const callerClose = conn.onClose;
28|    conn.onClose = () => {
29|      connections.delete(conn);
30|      callerClose?.();
31|    };
32|  });
33|  return { server, connections };
34|}
35|
36|if (import.meta.main) {
37|  // Usage: node server/main.mjs [--seed N] [port]. Flag and positional port
38|  // are parsed apart, in either order.
39|  const argv = process.argv.slice(2);
40|  const seedIx = argv.indexOf('--seed');
41|  const seed = seedIx === -1
42|    ? (Number.isFinite(Number(process.env.SEED)) && process.env.SEED !== '' ? Number(process.env.SEED) : DEFAULT_CITY.seed)
43|    : Number(argv[seedIx + 1]);
44|  const PORT = Number(argv.filter((a, i) => i !== seedIx && i !== seedIx + 1)[0] ?? process.env.PORT ?? 8080);
45|  // The server owns the rules and the seed; clients regenerate the same city
46|  // from it (phase 3). Rules are pure (raceState.js) and get everything from
47|  // here injected, so tests drive them over FakeNet instead of sockets.
48|  const race = createRaceState({
49|    seed,
50|    now: () => Date.now(),
51|    send: (conn, type, data) => conn.send(encode(type, data)),
52|    close: (conn, code, reason) => conn.close(code, reason),
53|    schedule: (delayMs, fn) => setTimeout(fn, delayMs), // real timers; tests swap in FakeNet.schedule
54|  });
55|  // 0.0.0.0: reachable from other machines on the intranet, not just localhost.
56|  createGameServer({
57|    onConnect: (conn) => {
58|      race.connect(conn);
59|      conn.onMessage = (text) => race.onMessage(conn, text);
60|      conn.onClose = () => race.disconnect(conn);
61|    },
62|  }).server.listen(PORT, '0.0.0.0', () =>
63|    console.log(`FairFahren server on http://0.0.0.0:${PORT} (game + WebSocket /ws, race seed ${seed})`));
64|}", "total_lines": 64, "file_size": 3044, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// The multiplayer message language: one entry per message type, declaring its
2|// direction ('cs' client → server, 'sc' server → client), its wire fields and
3|// its design rate. One shared encode/decode pair is driven by those entries,
4|// so every packet is validated against the same definitions that produce the
5|// protocol table in NOTES.md (`node tools/protocol-table.mjs`).
6|//
7|// Wire format: JSON text frames tagged with `type` — messages are tiny and the
8|// intranet is fast, so readable beats compact. All times are milliseconds in
9|// the shared server clock (clients learn their offset via ping/pong, because
10|// the browser's WebSocket API hides the protocol-level ping/pong from JS).
11|
12|export const STAGES = ['lobby', 'countdown', 'racing', 'finished', 'ceremony'];
13|export const MAX_PLAYERS = 4;
14|
15|const err = (where, why) => new Error(`protocol: ${where} ${why}`);
16|
17|// --- Field validators (used by encode AND decode, so both sides agree) ---
18|
19|function str(v, w) {
20|  if (typeof v !== 'string' || v.length < 1 || v.length > 24) throw err(w, 'must be a 1..24 char string');
21|  return v;
22|}
23|function num(v, w) {
24|  if (typeof v !== 'number' || !Number.isFinite(v)) throw err(w, 'must be a finite number');
25|  return v;
26|}
27|function idNum(v, w) {
28|  if (!Number.isInteger(v) || v < 1) throw err(w, 'must be a positive integer');
29|  return v;
30|}
31|function seedNum(v, w) {
32|  if (!Number.isInteger(v) || v < 0) throw err(w, 'must be a non-negative integer');
33|  return v;
34|}
35|function stageOf(v, w) {
36|  if (!STAGES.includes(v)) throw err(w, `must be one of ${STAGES.join('|')}`);
37|  return v;
38|}
39|function rosterOf(v, w) {
40|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
41|  return v.map((p, i) => {
42|    if (typeof p !== 'object' || p === null || Array.isArray(p)) throw err(`${w}[${i}]`, 'must be an object');
43|    for (const k of Object.keys(p)) if (k !== 'id' && k !== 'name') throw err(`${w}[${i}]`, `has unknown field ${k}`);
44|    if (!('id' in p) || !('name' in p)) throw err(`${w}[${i}]`, 'needs id and name');
45|    return { id: idNum(p.id, `${w}[${i}].id`), name: str(p.name, `${w}[${i}].name`) };
46|  });
47|}
48|
49|const tOrNull = (v, w) => (v === null ? null : num(v, w));
50|const boolOf = (v, w) => {
51|  if (typeof v !== 'boolean') throw err(w, 'must be a boolean');
52|  return v;
53|};
54|// One results-table row for the settled race: finished players first in
55|// official order (time, then earliest report), DNFs last with t = null.
56|const resultsOf = (v, w) => {
57|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
58|  return v.map((r, i) => {
59|    if (typeof r !== 'object' || r === null || Array.isArray(r)) throw err(`${w}[${i}]`, 'must be an object');
60|    for (const k of Object.keys(r)) if (k !== 'id' && k !== 'name' && k !== 't' && k !== 'dnf') throw err(`${w}[${i}]`, `has unknown field ${k}`);
61|    if (!('id' in r) || !('name' in r) || !('t' in r) || !('dnf' in r)) throw err(`${w}[${i}]`, 'needs id, name, t and dnf');
62|    return {
63|      id: idNum(r.id, `${w}[${i}].id`),
64|      name: str(r.name, `${w}[${i}].name`),
65|      t: tOrNull(r.t, `${w}[${i}].t`),
66|      dnf: boolOf(r.dnf, `${w}[${i}].dnf`),
67|    };
68|  });
69|};
70|
71|// --- The registry ---
72|
73|export const MESSAGES = {
74|  // client → server
75|  join:       { dir: 'cs', rate: 'once, on entering the lobby', fields: { name: str } },
76|  name:       { dir: 'cs', rate: 'on change, in lobby',          fields: { name: str } },
77|  start:      { dir: 'cs', rate: 'user-triggered',               fields: {} },
78|  pos:        { dir: 'cs', rate: '15 Hz while racing',           fields: { x: num, z: num, h: num, s: num } },
79|  finish:     { dir: 'cs', rate: 'once per race',                fields: { t: num } },
80|  ping:       { dir: 'cs', rate: 'about 1 Hz while syncing',     fields: { t: num } },
81|  // server → client
82|  roster:     { dir: 'sc', rate: 'on change',                    fields: { players: rosterOf, seed: seedNum } },
83|  countdown:  { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
84|  go:         { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
85|  posRelay:   { dir: 'sc', rate: 'per player, 15 Hz',            fields: { id: idNum, x: num, z: num, h: num, s: num } },
86|  stage:      { dir: 'sc', rate: 'on change',                    fields: { stage: stageOf } },
87|  disconnect: { dir: 'sc', rate: 'on player leaving',            fields: { id: idNum } },
88|  pong:       { dir: 'sc', rate: 'on ping',                      fields: { t: num, s: num } },
89|  finishInfo: { dir: 'sc', rate: 'per finisher, once',           fields: { id: idNum, t: num } },
90|  results:    { dir: 'sc', rate: 'once, when the race is settled', fields: { players: resultsOf } },
91|};
92|
93|// --- The encode/decode pair ---
94|
95|// encode(type, data) → JSON string, fields validated on the way out.
96|export function encode(type, data) {
97|  const def = MESSAGES[type];
98|  if (!def) throw err(type, 'is not a known message type');
99|  const out = { type };
100|  for (const [f, check] of Object.entries(def.fields)) out[f] = check(data?.[f], `${type}.${f}`);
101|  return JSON.stringify(out);
102|}
103|
104|// decode(text) → { type, data }, or throws on anything unknown or malformed:
105|// bad JSON, non-objects, unknown types, missing/unknown fields, wrong value types.
106|export function decode(text) {
107|  let m = null;
108|  try { m = JSON.parse(text); } catch { /* handled below */ }
109|  if (typeof m !== 'object' || m === null || Array.isArray(m)) throw err('packet', 'must be a JSON object');
110|  const def = MESSAGES[m.type];
111|  if (!def) throw err('packet', `unknown message type ${JSON.stringify(m.type)}`);
112|  const known = Object.keys(def.fields);
113|  for (const k of Object.keys(m)) if (k !== 'type' && !known.includes(k)) throw err(m.type, `unknown field ${k}`);
114|  const data = {};
115|  for (const [f, check] of Object.entries(def.fields)) data[f] = check(m[f], `${m.type}.${f}`);
116|  return { type: m.type, data };
117|}
118|
119|// Markdown table of the whole protocol, generated from the registry. NOTES.md
120|// embeds it between markers; a test keeps the two from drifting apart.
121|export function protocolTable() {
122|  const rows = Object.entries(MESSAGES).map(([name, d]) =>
123|    `| ${name} | ${d.dir === 'cs' ? 'client → server' : 'server → client'} | ${Object.keys(d.fields).join(' ') || '—'} | ${d.rate} |`);
124|  return ['| type | from | fields | rate |', '|---|---|---|---|', ...rows].join('\n');
125|}", "total_lines": 125, "file_size": 6448, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// In-memory stand-in for the real network: FakeServer hands out FakeConnection
2|// pairs (server side ↔ client side) whose messages are delivered straight to
3|// the peer's handler — immediately, after N ms on FakeNet's virtual clock, or
4|// never (drop). Race logic (phase 2) is driven end-to-end through these pairs
5|// with deterministic timestamps: no sockets, no real timers.
6|//
7|// The connection shape mirrors the real WsConnection from ws.js:
8|// send(text), close(), onMessage(cb), onClose(cb), plus a server-assigned id.
9|
10|// Virtual clock + FIFO event queue. advance(ms) runs everything that became
11|// due, in schedule order; handlers may schedule follow-ups mid-advance.
12|export class FakeNet {
13|  constructor(start = 0) {
14|    this.now = start;
15|    this.queue = []; // { at, seq, fn }, kept sorted by (at, seq)
16|    this._seq = 0;
17|  }
18|
19|  schedule(delay, fn) {
20|    this.queue.push({ at: this.now + Math.max(0, delay), seq: this._seq++, fn });
21|    this.queue.sort((a, b) => a.at - b.at || a.seq - b.seq);
22|  }
23|
24|  advance(ms) {
25|    const end = this.now + ms;
26|    while (this.queue.length && this.queue[0].at <= end) {
27|      this.now = this.queue[0].at;
28|      this.queue.shift().fn();
29|    }
30|    this.now = end;
31|  }
32|}
33|
34|const resolve = (v) => (typeof v === 'function' ? v() : v);
35|
36|// One end of a wire pair. opts: { latency = 0, drop = false } — plain values or
37|// functions, re-read on every send, so tests can inject jitter or selective loss.
38|export class FakeConnection {
39|  constructor(net, opts = {}) {
40|    this.net = net;
41|    this.opts = opts;
42|    this.id = 0;
43|    this.peer = null;
44|    this.onMessage = null;
45|    this.onClose = null;
46|    this.closed = false;
47|  }
48|
49|  send(text) {
50|    if (this.closed || resolve(this.opts.drop)) return;
51|    const peer = this.peer;
52|    const deliver = () => !peer.closed && peer.onMessage?.(text);
53|    const delay = resolve(this.opts.latency ?? 0);
54|    if (delay > 0) this.net.schedule(delay, deliver); else deliver();
55|  }
56|
57|  // Clean disconnect: the closer learns at once, the peer after the wire delay.
58|  // `code`/`reason` are ignored for delivery but recorded, so tests can verify
59|  // reject messages (the real WsConnection sends them in a close frame).
60|  close(code, reason) {
61|    if (this.closed) return;
62|    this.closed = true;
63|    this.closedWith = { code, reason };
64|    this.onClose?.();
65|    const peer = this.peer;
66|    const notify = () => peer._peerClosed();
67|    const delay = resolve(this.opts.latency ?? 0);
68|    if (delay > 0) this.net.schedule(delay, notify); else notify();
69|  }
70|
71|  _peerClosed() {
72|    if (this.closed) return;
73|    this.closed = true;
74|    this.onClose?.();
75|  }
76|}
77|
78|// Creates the pairs: every connect() makes a server-side connection (handed to
79|// onConnect, with a fresh id) and returns the matching client side.
80|export class FakeServer {
81|  constructor(net) {
82|    this.net = net;
83|    this.onConnect = null;
84|    this._nextId = 1;
85|  }
86|
87|  // Both directions share clientOpts unless serverOpts is given explicitly.
88|  connect(clientOpts = {}, serverOpts = clientOpts) {
89|    const serverConn = new FakeConnection(this.net, serverOpts);
90|    const clientConn = new FakeConnection(this.net, clientOpts);
91|    serverConn.peer = clientConn;
92|    clientConn.peer = serverConn;
93|    serverConn.id = this._nextId++;
94|    this.onConnect?.(serverConn);
95|    return clientConn;
96|  }
97|}", "total_lines": 97, "file_size": 3332, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Master-clock maths for the online race. PURE: no DOM, no timers — a client
3| * feeds it pong replies, it keeps the best estimate of the server clock.
4| *
5| * Why the app-level ping/pong instead of WebSocket pings? The browser API
6| * hides protocol-level pings from JavaScript, so the client sends `ping`
7| * {t: local send time}; the server replies `pong` {t: echoed, s: server clock}.
8| * With a roughly symmetric wire, the server's "now" sits in the middle of the
9| * round trip, giving the offset from the client clock to the server clock:
10| *
11| *   rtt    = receiveTime − sentT
12| *   offset = serverS + rtt / 2 − receiveTime   (serverNow = localNow + offset)
13| *
14| * Network jitter inflates individual rtts, so the estimate always comes from
15| * the sample with the SMALLEST rtt of the last N pongs: the fast samples
16| * waited least in queues, so distorted least. Clients keep re-syncing (the
17| * lobby pings at ~1 Hz) before the shared start moment counts down, and the
18| * same serverNow() decides when ONE shared goAt has arrived — so every
19| * client, whatever its wire, flips the ampel to green at the same server
20| * instant.
21| * Counts toward the size budget — kept tight.
22| */
23|
24|/** One clock. history = pong samples kept for the min-rtt filter. */
25|export function createClock(history = 8) {
26|  const samples = []; // {rtt, offset}, newest last
27|  return {
28|    /** Feed one pong: echoedT = our send timestamp echoed back, serverAt = server clock reading, receiveTime = local receive time. */
29|    onPong(echoedT, serverAt, receiveTime) {
30|      const rtt = Math.max(0, receiveTime - echoedT);
31|      samples.push({ rtt, offset: serverAt + rtt / 2 - receiveTime });
32|      while (samples.length > history) samples.shift();
33|    },
34|    /** Best offset estimate, or null before the first pong. */
35|    offset() {
36|      let best = null;
37|      for (const s of samples) if (!best || s.rtt < best.rtt) best = s;
38|      return best ? best.offset : null;
39|    },
40|    /** True once at least one pong has been measured. */
41|    synced() { return samples.length > 0; },
42|    /** Convert a local time to the master clock. Returns null while unsynced. */
43|    serverNow(localNow) {
44|      const offset = this.offset();
45|      return offset === null ? null : localNow + offset;
46|    },
47|  };
