{"content": "1|// RFC 6455 WebSocket, hand-rolled on the raw socket node:http hands us from the
2|// 'upgrade' event. Pure, byte-level pieces (handshake, framing, masking) that
3|// the unit tests can drive with Buffers. Scope: small unfragmented frames only
4|// (this is a LAN game with tiny JSON messages), so no fragmentation/extensions.
5|import { createHash } from 'node:crypto';
6|
7|export const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
8|export const OP = { text: 0x1, close: 0x8, ping: 0x9, pong: 0xa };
9|export const MAX_PAYLOAD = 65535; // frames above this are rejected (small frames only)
10|
11|// --- Handshake ---
12|
13|// RFC 6455 §4.2.2: base64(SHA-1(key + GUID)).
14|export function acceptKey(key) {
15|  return createHash('sha1').update(key + GUID).digest('base64');
16|}
17|
18|const KEY_RE = /^[A-Za-z0-9+/]{22}==$/; // base64 of the required 16 random bytes
19|
20|// Validate the headers of an upgrade request (node:http lowercases them).
21|// Returns { ok: true, key } or { ok: false, status, reason, extra }.
22|export function validateUpgrade(h) {
23|  if (!h || h.upgrade?.toLowerCase() !== 'websocket')
24|    return { ok: false, status: 400, reason: 'Bad Request' };
25|  const tokens = (h.connection ?? '').toLowerCase().split(',').map((s) => s.trim());
26|  if (!tokens.includes('upgrade'))
27|    return { ok: false, status: 400, reason: 'Bad Request' };
28|  if (h['sec-websocket-version'] !== '13')
29|    return { ok: false, status: 426, reason: 'Upgrade Required', extra: 'Sec-WebSocket-Version: 13\r\n' };
30|  const key = h['sec-websocket-key'];
31|  if (typeof key !== 'string' || !KEY_RE.test(key))
32|    return { ok: false, status: 400, reason: 'Bad Request' };
33|  return { ok: true, key };
34|}
35|
36|// The full 101 reply that switches the HTTP connection into WebSocket mode.
37|export function handshakeResponse(key) {
38|  return `HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${acceptKey(key)}\r\n\r\n`;
39|}
40|
41|// --- Framing ---
42|
43|// XOR the payload with the 4 mask bytes, in place (symmetric: mask twice = original).
44|export function applyMask(data, mask) {
45|  for (let i = 0; i < data.length; i++) data[i] ^= mask[i & 3];
46|  return data;
47|}
48|
49|// Encode one unmasked server frame (server frames are never masked, RFC §5.1).
50|export function encodeFrame(opcode, payload = '') {
51|  const data = typeof payload === 'string' ? Buffer.from(payload, 'utf8') : Buffer.from(payload);
52|  if (data.length > MAX_PAYLOAD) throw new Error('ws: frame too large');
53|  if (opcode > 7 && data.length > 125) throw new Error('ws: control frame payload > 125');
54|  const head = data.length < 126 ? Buffer.from([0x80 | opcode, data.length]) : Buffer.alloc(4);
55|  if (head.length === 4) { // 126..65535 bytes: 16-bit extended length
56|    head[0] = 0x80 | opcode; head[1] = 126; head.writeUInt16BE(data.length, 2);
57|  }
58|  return Buffer.concat([head, data]);
59|}
60|
61|const KNOWN_OPCODES = new Set([0x1, 0x2, 0x8, 0x9, 0xa]);
62|
63|// Try to decode ONE frame from the front of `buf`. Returns null while more bytes
64|// are needed; otherwise { fin, opcode, masked, payload, bytes } with the payload
65|// unmasked and copied (the caller keeps `buf`) and `bytes` = total frame size.
66|// Throws on protocol violations (reserved bits, fragments, oversized control frames).
67|export function decodeFrame(buf) {
68|  if (buf.length < 2) return null;
69|  const fin = (buf[0] & 0x80) !== 0, rsv = buf[0] & 0x70, opcode = buf[0] & 0x0f;
70|  const masked = (buf[1] & 0x80) !== 0;
71|  let len = buf[1] & 0x7f, off = 2;
72|  if (rsv !== 0) throw new Error('ws: reserved bits set');
73|  if (!KNOWN_OPCODES.has(opcode)) throw new Error('ws: reserved opcode');
74|  if (!fin) throw new Error('ws: fragmented frames not supported');
75|  if (len === 127) throw new Error('ws: 64-bit frame lengths not supported');
76|  if (len === 126) {
77|    if (buf.length < 4) return null;
78|    len = buf.readUInt16BE(2); off = 4;
79|  }
80|  if (opcode > 7 && len > 125) throw new Error('ws: control frame payload > 125');
81|  if (masked && buf.length < off + 4) return null;
82|  const mask = masked ? buf.subarray(off, off + 4) : null;
83|  if (masked) off += 4;
84|  if (buf.length < off + len) return null;
85|  const payload = Buffer.from(buf.subarray(off, off + len));
86|  if (mask) applyMask(payload, mask);
87|  return { fin, opcode, masked, payload, bytes: off + len };
88|}
89|
90|// Incremental reader for a stream: pass it arbitrary chunks, it emits complete
91|// frames via `onFrame` in arrival order and lets protocol errors propagate.
92|export function createFrameReader(onFrame) {
93|  let buf = null;
94|  return (chunk) => {
95|    buf = buf ? Buffer.concat([buf, chunk]) : Buffer.from(chunk);
96|    for (;;) {
97|      if (!buf) return;
98|      const f = decodeFrame(buf);
99|      if (!f) return;
100|      buf = f.bytes < buf.length ? buf.subarray(f.bytes) : null;
101|      onFrame(f);
102|    }
103|  };
104|}
105|
106|// --- Connection: one live WebSocket over an upgraded socket ---
107|
108|// 2-byte close code + optional utf8 reason (control payload limit: 125 bytes).
109|function closePayload(code, reason) {
110|  const r = Buffer.from(String(reason ?? ''), 'utf8').subarray(0, 123);
111|  return Buffer.concat([Buffer.from([code >> 8, code & 0xff]), r]);
112|}
113|
114|// Validate the upgrade, write the 101 reply, wrap the socket. Returns a
115|// WsConnection, or null after answering + closing an invalid handshake.
116|// (socket.end, never destroy-after-write: destroy discards unflushed bytes.)
117|export function acceptConnection(socket, headers) {
118|  const v = validateUpgrade(headers);
119|  if (!v.ok) {
120|    socket.on('error', () => {});
121|    socket.end(`HTTP/1.1 ${v.status} ${v.reason}\r\n${v.extra ?? ''}Connection: close\r\nContent-Length: 0\r\n\r\n`);
122|    return null;
123|  }
124|  socket.write(handshakeResponse(v.key));
125|  return new WsConnection(socket);
126|}
127|
128|export class WsConnection {
129|  // Text frames come out as onMessage(string); pings are answered with pongs
130|  // automatically; a close from either side ends the socket and fires onClose
131|  // exactly once. Binary frames are refused (the protocol is JSON text only).
132|  constructor(socket) {
133|    this.socket = socket;
134|    this.onMessage = null;
135|    this.onClose = null;
136|    this.open = true;
137|    this.closing = false;
138|    socket.setNoDelay(true); // latency matters more than bandwidth here
139|    const reader = createFrameReader((f) => this._onFrame(f));
140|    socket.on('data', (chunk) => { try { reader(chunk); } catch { this._close(1002, 'protocol error'); } });
141|    socket.on('error', () => {}); // socket errors surface as 'close', never a crash
142|    socket.on('close', () => this._closed());
143|  }
144|
145|  send(text) { this._send(OP.text, Buffer.from(String(text), 'utf8')); }
146|  close(code = 1000, reason = '') { this._close(code, reason); }
147|
148|  _onFrame(f) {
149|    if (f.opcode === OP.ping) return this._send(OP.pong, f.payload);
150|    if (f.opcode === OP.pong) return; // RTT is measured with app-level ping/pong messages
151|    if (f.opcode === OP.close) {
152|      const code = f.payload.length >= 2 ? f.payload.readUInt16BE(0) : 1000;
153|      return this._close(code, ''); // echo the close, then end
154|    }
155|    if (f.opcode === OP.text) return this.onMessage?.(f.payload.toString('utf8'));
156|    this._close(1003, 'binary not supported');
157|  }
158|
159|  _send(opcode, payload) {
160|    if (this.closing) return;
161|    try { this.socket.write(encodeFrame(opcode, payload)); } catch { /* socket died mid-write */ }
162|  }
163|
164|  // Send a close frame, then end the socket (end flushes; destroy would not).
165|  _close(code, reason) {
166|    if (this.closing) return;
167|    this._send(OP.close, closePayload(code, reason));
168|    this.closing = true;
169|    this.socket.end();
170|  }
171|
172|  _closed() {
173|    if (!this.open) return;
174|    this.open = false;
175|    this.onClose?.();
176|  }
177|}", "total_lines": 177, "file_size": 7577, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

